mapper.select:
SELECT P.PRJ_NAME
FROM project P
WHERE P.ID = #{prjId}

SELECT G.ID
FROM GRP G
WHERE G.PRJ_ID = #{prjId}
  AND G.NAME = #{grpName}
  AND G.STATUS_CD = '01ACTIVE'

SELECT COUNT(*)
FROM GRP G
WHERE G.PRJ_ID = #{prjId}
  AND G.NAME = #{grpName}
  AND G.STATUS_CD = '01ACTIVE'

SELECT COUNT(*)
FROM GRP_ROLE GR
INNER JOIN GRP G
  ON G.ID = GR.GRP_ID
 AND G.PRJ_ID = #{prjId}
 AND G.STATUS_CD = '01ACTIVE'
INNER JOIN ROLE R
  ON R.ROLE_CD = GR.ROLE_CD
 AND R.PRJ_ID = #{prjId}
WHERE GR.GRP_ID = #{grpId}
  AND GR.ROLE_CD = #{roleCd}

